actions.command:
mkdir -p /workspace/regex && cat > /workspace/regex/parse.go <<'EOF'
// Package regex implements a backtracking regular expression engine with
// .NET-style syntax and semantics (lookaround, backreferences, lazy
// quantifiers, Unicode character classes, inline flags).
package regex

import (
	"fmt"
	"strconv"
	"strings"
	"unicode"
)

// Flags controls regex compilation.
type Flags uint

const (
	IgnoreCase Flags = 1 << iota
	Multiline
	DotAll
	IgnoreWhitespace
)

type node interface{}

type litNode struct {
	r    rune
	fold bool
}

type classNode struct {
	set  *charSet
	fold bool
}

type anyNode struct {
	dotall bool
}

type seqNode struct {
	items []node
}

type altNode struct {
	alts []node
}

type groupNode struct {
	idx int
	sub node
}

type repNode struct {
	sub    node
	min    int
	max    int // -1 = unbounded
	greedy bool
}

const (
	assertBOL = iota
	assertEOL
	assertBOLNoML
	assertEOLNoML
	assertBOT // \A
	assertEOT // \z
	assertEOTNL // \Z
	assertWordB
	assertNotWordB
	assertStart // \G
)

type assertNode struct {
	kind int
}

type lookNode struct {
	sub    node
	neg    bool
	behind bool
	minLen int
	maxLen int
}

type atomicNode struct {
	sub node
}

type backrefNode struct {
	idx  int
	fold bool
}

type emptyNode struct{}

// Regex is a compiled regular expression.
type Regex struct {
	pattern   string
	root      node
	numGroups int // number of capture groups including group 0
	names     map[string]int
}

type parser struct {
	src       []rune
	pos       int
	flags     Flags
	groupNum  int
	names     map[string]int
	nameOrder []string
	totalUnnamed int
}

// Compile parses a pattern.
func Compile(pattern string, flags Flags) (re *Regex, err error) {
	defer func() {
		if r := recover(); r != nil {
			if pe, ok := r.(parseError); ok {
				err = pe
				return
			}
			panic(r)
		}
	}()
	p := &parser{src: []rune(pattern), flags: flags, names: map[string]int{}}
	p.totalUnnamed = p.countUnnamedGroups()
	p.groupNum = 0
	// Pre-assign names so they get numbers after unnamed groups.
	root := p.parseAlt()
	if p.pos < len(p.src) {
		if p.src[p.pos] == ')' {
			p.fail("unmatched )")
		}
		p.fail("unexpected character")
	}
	re = &Regex{pattern: pattern, root: root, numGroups: p.totalUnnamed + len(p.nameOrder) + 1, names: p.names}
	return re, nil
}

// MustCompile is like Compile but panics on error.
func MustCompile(pattern string, flags Flags) *Regex {
	re, err := Compile(pattern, flags)
	if err != nil {
		panic(err)
	}
	return re
}

type parseError struct {
	msg string
}

func (e parseError) Error() string { return e.msg }

func (p *parser) fail(msg string) {
	panic(parseError{fmt.Sprintf("regex: %s at position %d in %q", msg, p.pos, string(p.src))})
}

// countUnnamedGroups does a rough pre-scan to count unnamed capturing groups
// so that named groups can be numbered after them (as in .NET).
func (p *parser) countUnnamedGroups() int {
	n := 0
	inClass := false
	for i := 0; i < len(p.src); i++ {
		c := p.src[i]
		if c == '\\' {
			i++
			continue
		}
		if inClass {
			if c == ']' {
				inClass = false
			}
			continue
		}
		if c == '[' {
			inClass = true
			continue
		}
		if c == '(' {
			if i+1 < len(p.src) && p.src[i+1] == '?' {
				// named group?
				if i+2 < len(p.src) && (p.src[i+2] == '<' || p.src[i+2] == '\'' || p.src[i+2] == 'P') {
					// (?<name> is named; (?<= and (?<! are lookbehinds
					if p.src[i+2] == '<' && i+3 < len(p.src) && (p.src[i+3] == '=' || p.src[i+3] == '!') {
						continue
					}
					continue
				}
				continue
			}
			n++
		}
	}
	return n
}

func (p *parser) more() bool { return p.pos < len(p.src) }
func (p *parser) peek() rune  { return p.src[p.pos] }

func (p *parser) skipWS() {
	if p.flags&IgnoreWhitespace == 0 {
		return
	}
	for p.more() {
		c := p.peek()
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v' {
			p.pos++
		} else if c == '#' {
			for p.more() && p.peek() != '\n' {
				p.pos++
			}
		} else {
			break
		}
	}
}

func (p *parser) parseAlt() node {
	var alts []node
	for {
		alts = append(alts, p.parseSeq())
		if p.more() && p.peek() == '|' {
			p.pos++
			continue
		}
		break
	}
	if len(alts) == 1 {
		return alts[0]
	}
	return &altNode{alts: alts}
}

func (p *parser) parseSeq() node {
	var items []node
	for {
		p.skipWS()
		if !p.more() {
			break
		}
		c := p.peek()
		if c == '|' || c == ')' {
			break
		}
		atom := p.parseAtom()
		if atom == nil {
			continue
		}
		atom = p.parseQuantifier(atom)
		items = append(items, atom)
	}
	if len(items) == 0 {
		return &emptyNode{}
	}
	if len(items) == 1 {
		return items[0]
	}
	return &seqNode{items: items}
}

func (p *parser) parseQuantifier(atom node) node {
	for {
		p.skipWS()
		if !p.more() {
			return atom
		}
		c := p.peek()
		min, max := 0, 0
		switch c {
		case '*':
			min, max = 0, -1
			p.pos++
		case '+':
			min, max = 1, -1
			p.pos++
		case '?':
			min, max = 0, 1
			p.pos++
		case '{':
			ok, mn, mx, np := p.tryParseBraces(p.pos)
			if !ok {
				return atom
			}
			min, max = mn, mx
			p.pos = np
		default:
			return atom
		}
		greedy := true
		if p.more() && p.peek() == '?' {
			greedy = false
			p.pos++
		}
		switch atom.(type) {
		case *assertNode, *lookNode:
			// Quantified assertions: .NET allows some; treat {0,1}/? as optional assertion.
		}
		atom = &repNode{sub: atom, min: min, max: max, greedy: greedy}
		// .NET: nested quantifiers are an error; but allow continuing in case
		// of things like a{2}? handled above. Any further quantifier is an error.
		p.skipWS()
		if p.more() {
			c2 := p.peek()
			if c2 == '*' || c2 == '+' || c2 == '?' {
				p.fail("nested quantifier")
			}
			if c2 == '{' {
				if ok, _, _, _ := p.tryParseBraces(p.pos); ok {
					p.fail("nested quantifier")
				}
			}
		}
		return atom
	}
}

// tryParseBraces parses {n}, {n,}, {n,m} starting at i (src[i]=='{').
func (p *parser) tryParseBraces(i int) (ok bool, min, max, next int) {
	j := i + 1
	start := j
	for j < len(p.src) && p.src[j] >= '0' && p.src[j] <= '9' {
		j++
	}
	if j == start {
		return false, 0, 0, i
	}
	min, _ = strconv.Atoi(string(p.src[start:j]))
	if j < len(p.src) && p.src[j] == '}' {
		return true, min, min, j + 1
	}
	if j >= len(p.src) || p.src[j] != ',' {
		return false, 0, 0, i
	}
	j++
	start2 := j
	for j < len(p.src) && p.src[j] >= '0' && p.src[j] <= '9' {
		j++
	}
	if j >= len(p.src) || p.src[j] != '}' {
		return false, 0, 0, i
	}
	if j == start2 {
		return true, min, -1, j + 1
	}
	max, _ = strconv.Atoi(string(p.src[start2:j]))
	if max < min {
		p.fail("illegal {x,y} with x > y")
	}
	return true, min, max, j + 1
}

func (p *parser) parseAtom() node {
	c := p.peek()
	fold := p.flags&IgnoreCase != 0
	switch c {
	case '(':
		return p.parseGroup()
	case '[':
		p.pos++
		set := p.parseClass()
		return &classNode{set: set, fold: fold}
	case '.':
		p.pos++
		return &anyNode{dotall: p.flags&DotAll != 0}
	case '^':
		p.pos++
		if p.flags&Multiline != 0 {
			return &assertNode{kind: assertBOL}
		}
		return &assertNode{kind: assertBOLNoML}
	case '$':
		p.pos++
		if p.flags&Multiline != 0 {
			return &assertNode{kind: assertEOL}
		}
		return &assertNode{kind: assertEOLNoML}
	case '\\':
		return p.parseEscape()
	case '*', '+', '?':
		p.fail("quantifier following nothing")
	case '{':
		if ok, _, _, _ := p.tryParseBraces(p.pos); ok {
			p.fail("quantifier following nothing")
		}
		p.pos++
		return &litNode{r: c, fold: fold}
	default:
		p.pos++
		return &litNode{r: c, fold: fold}
	}
	return nil
}

func (p *parser) parseGroup() node {
	// at '('
	p.pos++
	if !p.more() {
		p.fail("unterminated group")
	}
	savedFlags := p.flags
	defer func() { p.flags = savedFlags }()
	if p.peek() != '?' {
		p.groupNum++
		idx := p.groupNum
		sub := p.parseAlt()
		p.expect(')')
		return &groupNode{idx: idx, sub: sub}
	}
	p.pos++ // '?'
	if !p.more() {
		p.fail("unterminated group")
	}
	c := p.peek()
	switch c {
	case ':':
		p.pos++
		sub := p.parseAlt()
		p.expect(')')
		return wrapNonCapture(sub)
	case '=', '!':
		p.pos++
		sub := p.parseAlt()
		p.expect(')')
		return &lookNode{sub: sub, neg: c == '!'}
	case '>':
		p.pos++
		sub := p.parseAlt()
		p.expect(')')
		return &atomicNode{sub: sub}
	case '#':
		for p.more() && p.peek() != ')' {
			p.pos++
		}
		p.expect(')')
		return nil
	case '<', '\'', 'P':
		if c == 'P' {
			p.pos++
			if !p.more() || p.peek() != '<' {
				p.fail("bad (?P")
			}
			c = '<'
		}
		p.pos++
		if c == '<' && p.more() && (p.peek() == '=' || p.peek() == '!') {
			neg := p.peek() == '!'
			p.pos++
			sub := p.parseAlt()
			p.expect(')')
			mn, mx := widths(sub)
			return &lookNode{sub: sub, neg: neg, behind: true, minLen: mn, maxLen: mx}
		}
		closer := '>'
		if c == '\'' {
			closer = '\''
		}
		start := p.pos
		for p.more() && p.peek() != closer {
			p.pos++
		}
		if !p.more() {
			p.fail("unterminated group name")
		}
		name := string(p.src[start:p.pos])
		p.pos++
		var idx int
		if n, err := strconv.Atoi(name); err == nil && n >= 0 {
			idx = n
		} else {
			if existing, ok := p.names[name]; ok {
				idx = existing
			} else {
				idx = p.totalUnnamed + len(p.nameOrder) + 1
				p.names[name] = idx
				p.nameOrder = append(p.nameOrder, name)
			}
		}
		sub := p.parseAlt()
		p.expect(')')
		return &groupNode{idx: idx, sub: sub}
	case '(':
		p.fail("conditionals not supported")
	default:
		// inline flags: (?imsx-imsx) or (?imsx-imsx:...)
		on := true
		newFlags := p.flags
		for p.more() {
			ch := p.peek()
			switch ch {
			case 'i':
				newFlags = setFlag(newFlags, IgnoreCase, on)
			case 'm':
				newFlags = setFlag(newFlags, Multiline, on)
			case 's':
				newFlags = setFlag(newFlags, DotAll, on)
			case 'x':
				newFlags = setFlag(newFlags, IgnoreWhitespace, on)
			case 'n':
				// explicit capture: ignore
			case '-':
				on = false
			case ')':
				p.pos++
				// flags apply to the rest of the enclosing group
				p.flags = newFlags
				savedFlags = newFlags
				return nil
			case ':':
				p.pos++
				p.flags = newFlags
				sub := p.parseAlt()
				p.expect(')')
				return wrapNonCapture(sub)
			default:
				p.fail("unknown group flag")
			}
			p.pos++
		}
		p.fail("unterminated flags group")
	}
	return nil
}

func wrapNonCapture(sub node) node {
	// Use a group with idx 0 wrapper not needed; return sub directly but
	// ensure it quantifies as a unit (seq/alt are already units).
	return &groupNode{idx: -1, sub: sub}
}

func setFlag(f Flags, bit Flags, on bool) Flags {
	if on {
		return f | bit
	}
	return f &^ bit
}

func (p *parser) expect(c rune) {
	if !p.more() || p.peek() != c {
		p.fail(fmt.Sprintf("expected %q", c))
	}
	p.pos++
}

func (p *parser) parseEscape() node {
	// at '\\'
	p.pos++
	if !p.more() {
		p.fail("trailing backslash")
	}
	fold := p.flags&IgnoreCase != 0
	c := p.peek()
	p.pos++
	switch c {
	case 'A':
		return &assertNode{kind: assertBOT}
	case 'z':
		return &assertNode{kind: assertEOT}
	case 'Z':
		return &assertNode{kind: assertEOTNL}
	case 'b':
		return &assertNode{kind: assertWordB}
	case 'B':
		return &assertNode{kind: assertNotWordB}
	case 'G':
		return &assertNode{kind: assertStart}
	case 'd', 'D', 'w', 'W', 's', 'S':
		set := newCharSet()
		addClassEscape(set, c)
		return &classNode{set: set, fold: fold}
	case 'p', 'P':
		set := newCharSet()
		p.parseUnicodeClass(set, c == 'P')
		return &classNode{set: set, fold: fold}
	case 'k':
		if !p.more() || (p.peek() != '<' && p.peek() != '\'') {
			p.fail("bad \\k")
		}
		closer := '>'
		if p.peek() == '\'' {
			closer = '\''
		}
		p.pos++
		start := p.pos
		for p.more() && p.peek() != closer {
			p.pos++
		}
		name := string(p.src[start:p.pos])
		p.expect(closer)
		idx, ok := p.names[name]
		if !ok {
			if n, err := strconv.Atoi(name); err == nil {
				idx = n
			} else {
				p.fail("undefined group name")
			}
		}
		return &backrefNode{idx: idx, fold: fold}
	case '1', '2', '3', '4', '5', '6', '7', '8', '9':
		// backreference (possibly multi-digit)
		start := p.pos - 1
		j := p.pos
		for j < len(p.src) && p.src[j] >= '0' && p.src[j] <= '9' {
			j++
		}
		num, _ := strconv.Atoi(string(p.src[start:j]))
		total := p.totalUnnamed
		if num <= total || num < 10 {
			if num > total && num >= 8 {
				// \8 \9 with no such group: literal in .NET? Treat as error -> literal
			}
			p.pos = j
			return &backrefNode{idx: num, fold: fold}
		}
		// try single digit
		p.pos = start + 1
		num = int(p.src[start] - '0')
		return &backrefNode{idx: num, fold: fold}
	case '0':
		// octal: up to 2 more octal digits
		v := 0
		n := 0
		for n < 2 && p.more() && p.peek() >= '0' && p.peek() <= '7' {
			v = v*8 + int(p.peek()-'0')
			p.pos++
			n++
		}
		return &litNode{r: rune(v), fold: fold}
	default:
		r := p.simpleEscape(c)
		return &litNode{r: r, fold: fold}
	}
}

// simpleEscape handles escapes that produce a single literal rune.
func (p *parser) simpleEscape(c rune) rune {
	switch c {
	case 'n':
		return '\n'
	case 't':
		return '\t'
	case 'r':
		return '\r'
	case 'f':
		return '\f'
	case 'v':
		return '\v'
	case 'a':
		return '\a'
	case 'e':
		return 0x1b
	case 'x':
		return rune(p.parseHex(2))
	case 'u':
		return rune(p.parseHex(4))
	case 'c':
		if !p.more() {
			p.fail("bad \\c")
		}
		ch := p.peek()
		p.pos++
		return unicode.ToUpper(ch) - '@'
	default:
		return c
	}
}

func (p *parser) parseHex(n int) int {
	if p.pos+n > len(p.src) {
		p.fail("bad hex escape")
	}
	v, err := strconv.ParseUint(string(p.src[p.pos:p.pos+n]), 16, 32)
	if err != nil {
		p.fail("bad hex escape")
	}
	p.pos += n
	return int(v)
}

func (p *parser) parseUnicodeClass(set *charSet, negate bool) {
	if !p.more() || p.peek() != '{' {
		p.fail("bad \\p")
	}
	p.pos++
	start := p.pos
	for p.more() && p.peek() != '}' {
		p.pos++
	}
	name := string(p.src[start:p.pos])
	p.expect('}')
	tbl := lookupUnicodeTable(name)
	if tbl == nil {
		p.fail("unknown unicode category " + name)
	}
	if negate {
		set.negTables = append(set.negTables, tbl)
	} else {
		set.tables = append(set.tables, tbl)
	}
}

func lookupUnicodeTable(name string) *unicode.RangeTable {
	if t, ok := unicode.Categories[name]; ok {
		return t
	}
	if t, ok := unicode.Scripts[name]; ok {
		return t
	}
	if strings.HasPrefix(name, "Is") {
		if t, ok := unicode.Scripts[name[2:]]; ok {
			return t
		}
		if t, ok := unicode.Categories[name[2:]]; ok {
			return t
		}
		// named blocks
		if t, ok := namedBlocks[name[2:]]; ok {
			return t
		}
	}
	if name == "Cn" {
		return unassignedTable()
	}
	return nil
}

var namedBlocks = map[string]*unicode.RangeTable{
	"BasicLatin":            {R16: []unicode.Range16{{0x0000, 0x007f, 1}}},
	"Latin-1Supplement":     {R16: []unicode.Range16{{0x0080, 0x00ff, 1}}},
	"LatinExtended-A":       {R16: []unicode.Range16{{0x0100, 0x017f, 1}}},
	"LatinExtended-B":       {R16: []unicode.Range16{{0x0180, 0x024f, 1}}},
	"GeneralPunctuation":    {R16: []unicode.Range16{{0x2000, 0x206f, 1}}},
	"CJKUnifiedIdeographs":  {R16: []unicode.Range16{{0x4e00, 0x9fff, 1}}},
	"Hiragana":              {R16: []unicode.Range16{{0x3040, 0x309f, 1}}},
	"Katakana":              {R16: []unicode.Range16{{0x30a0, 0x30ff, 1}}},
	"Cyrillic":              {R16: []unicode.Range16{{0x0400, 0x04ff, 1}}},
	"Greek":                 {R16: []unicode.Range16{{0x0370, 0x03ff, 1}}},
	"GreekandCoptic":        {R16: []unicode.Range16{{0x0370, 0x03ff, 1}}},
	"Arabic":                {R16: []unicode.Range16{{0x0600, 0x06ff, 1}}},
	"Hebrew":                {R16: []unicode.Range16{{0x0590, 0x05ff, 1}}},
	"BoxDrawing":            {R16: []unicode.Range16{{0x2500, 0x257f, 1}}},
	"MathematicalOperators": {R16: []unicode.Range16{{0x2200, 0x22ff, 1}}},
}

var unassigned *unicode.RangeTable

func unassignedTable() *unicode.RangeTable {
	if unassigned != nil {
		return unassigned
	}
	var r16 []unicode.Range16
	var r32 []unicode.Range32
	start := -1
	for r := rune(0); r <= unicode.MaxRune; r++ {
		assigned := false
		for _, t := range unicode.Categories {
			if len(t.R16) == 0 && len(t.R32) == 0 {
				continue
			}
			if unicode.Is(t, r) {
				assigned = true
				break
			}
		}
		if !assigned {
			if start < 0 {
				start = int(r)
			}
		} else if start >= 0 {
			addRange(&r16, &r32, start, int(r)-1)
			start = -1
		}
	}
	if start >= 0 {
		addRange(&r16, &r32, start, int(unicode.MaxRune))
	}
	unassigned = &unicode.RangeTable{R16: r16, R32: r32}
	return unassigned
}

func addRange(r16 *[]unicode.Range16, r32 *[]unicode.Range32, lo, hi int) {
	if hi <= 0xffff {
		*r16 = append(*r16, unicode.Range16{Lo: uint16(lo), Hi: uint16(hi), Stride: 1})
	} else if lo > 0xffff {
		*r32 = append(*r32, unicode.Range32{Lo: uint32(lo), Hi: uint32(hi), Stride: 1})
	} else {
		*r16 = append(*r16, unicode.Range16{Lo: uint16(lo), Hi: 0xffff, Stride: 1})
		*r32 = append(*r32, unicode.Range32{Lo: 0x10000, Hi: uint32(hi), Stride: 1})
	}
}

// parseClass parses a character class; p.pos is just after '['.
func (p *parser) parseClass() *charSet {
	set := newCharSet()
	if p.more() && p.peek() == '^' {
		set.negate = true
		p.pos++
	}
	first := true
	for {
		if !p.more() {
			p.fail("unterminated character class")
		}
		c := p.peek()
		if c == ']' && !first {
			p.pos++
			break
		}
		first = false
		// subtraction: -[...]
		if c == '-' && p.pos+1 < len(p.src) && p.src[p.pos+1] == '[' {
			p.pos += 2
			sub := p.parseClass()
			set.subtract = sub
			if !p.more() || p.peek() != ']' {
				p.fail("subtraction must be last in class")
			}
			p.pos++
			break
		}
		var lo rune
		isSingle := true
		if c == '\\' {
			p.pos++
			if !p.more() {
				p.fail("unterminated escape in class")
			}
			e := p.peek()
			p.pos++
			switch e {
			case 'd', 'D', 'w', 'W', 's', 'S':
				addClassEscape(set, e)
				isSingle = false
			case 'p', 'P':
				p.parseUnicodeClass(set, e == 'P')
				isSingle = false
			case 'b':
				lo = '\b'
			case '0':
				v := 0
				n := 0
				for n < 2 && p.more() && p.peek() >= '0' && p.peek() <= '7' {
					v = v*8 + int(p.peek()-'0')
					p.pos++
					n++
				}
				lo = rune(v)
			case '1', '2', '3', '4', '5', '6', '7':
				// octal in class
				v := int(e - '0')
				n := 1
				for n < 3 && p.more() && p.peek() >= '0' && p.peek() <= '7' {
					v = v*8 + int(p.peek()-'0')
					p.pos++
					n++
				}
				lo = rune(v)
			default:
				lo = p.simpleEscape(e)
			}
		} else {
			p.pos++
			lo = c
		}
		if !isSingle {
			continue
		}
		// range?
		if p.more() && p.peek() == '-' && p.pos+1 < len(p.src) && p.src[p.pos+1] != ']' {
			// check for subtraction
			if p.src[p.pos+1] == '[' {
				set.addRange(lo, lo)
				continue
			}
			p.pos++
			hc := p.peek()
			var hi rune
			if hc == '\\' {
				p.pos++
				if !p.more() {
					p.fail("unterminated escape in class")
				}
				e := p.peek()
				p.pos++
				switch e {
				case 'd', 'D', 'w', 'W', 's', 'S', 'p', 'P':
					p.fail("bad range in class")
				case 'b':
					hi = '\b'
				default:
					hi = p.simpleEscape(e)
				}
			} else {
				p.pos++
				hi = hc
			}
			if hi < lo {
				p.fail("reversed range in class")
			}
			set.addRange(lo, hi)
		} else {
			set.addRange(lo, lo)
		}
	}
	return set
}

func addClassEscape(set *charSet, c rune) {
	switch c {
	case 'd':
		set.tables = append(set.tables, unicode.Nd)
	case 'D':
		set.negTables = append(set.negTables, unicode.Nd)
	case 'w':
		set.word = true
	case 'W':
		set.negWord = true
	case 's':
		set.space = true
	case 'S':
		set.negSpace = true
	}
}

// widths computes the minimum and maximum (or -1) match width of a node.
func widths(n node) (int, int) {
	switch n := n.(type) {
	case *litNode, *classNode, *anyNode:
		return 1, 1
	case *emptyNode, *assertNode, *lookNode:
		return 0, 0
	case *seqNode:
		mn, mx := 0, 0
		for _, it := range n.items {
			a, b := widths(it)
			mn += a
			if mx >= 0 {
				if b < 0 {
					mx = -1
				} else {
					mx += b
				}
			}
		}
		return mn, mx
	case *altNode:
		mn, mx := -1, 0
		for _, a := range n.alts {
			x, y := widths(a)
			if mn < 0 || x < mn {
				mn = x
			}
			if mx >= 0 {
				if y < 0 {
					mx = -1
				} else if y > mx {
					mx = y
				}
			}
		}
		if mn < 0 {
			mn = 0
		}
		return mn, mx
	case *groupNode:
		return widths(n.sub)
	case *atomicNode:
		return widths(n.sub)
	case *repNode:
		a, b := widths(n.sub)
		mn := a * n.min
		mx := -1
		if n.max >= 0 && b >= 0 {
			mx = b * n.max
		}
		return mn, mx
	case *backrefNode:
		return 0, -1
	}
	return 0, -1
}

// NumGroups returns the number of capture groups (including group 0).
func (re *Regex) NumGroups() int { return re.numGroups }

// GroupIndex returns the index of a named group, or -1.
func (re *Regex) GroupIndex(name string) int {
	if i, ok := re.names[name]; ok {
		return i
	}
	return -1
}

// GroupNames returns a map of group names to indices.
func (re *Regex) GroupNames() map[string]int { return re.names }

// String returns the source pattern.
func (re *Regex) String() string { return re.pattern }
