package regex

import "unicode"

type matcher struct {
	in    []rune
	caps  []int
	start int
}

// MatchAt attempts to match the regex anchored at pos in input. It returns the
// capture positions (2 ints per group, -1 for unset) or nil if no match.
func (re *Regex) MatchAt(input []rune, pos int) []int {
	m := &matcher{in: input, caps: make([]int, 2*re.numGroups), start: pos}
	for i := range m.caps {
		m.caps[i] = -1
	}
	end := -1
	ok := m.match(re.root, pos, func(e int) bool {
		end = e
		return true
	})
	if !ok {
		return nil
	}
	m.caps[0] = pos
	m.caps[1] = end
	return m.caps
}

// MatchString is a convenience for tests: finds the first match anywhere.
func (re *Regex) FindIndex(input []rune, from int) []int {
	for p := from; p <= len(input); p++ {
		if c := re.MatchAt(input, p); c != nil {
			return c
		}
	}
	return nil
}

func foldEq(a, b rune) bool {
	if a == b {
		return true
	}
	if unicode.ToLower(a) == unicode.ToLower(b) {
		return true
	}
	if unicode.ToUpper(a) == unicode.ToUpper(b) {
		return true
	}
	for f := unicode.SimpleFold(a); f != a; f = unicode.SimpleFold(f) {
		if f == b {
			return true
		}
	}
	return false
}

// singleMatcher returns a function matching a single rune if the node is a
// single-character node.
func singleMatcher(n node) func(r rune) bool {
	switch n := n.(type) {
	case *litNode:
		if n.fold {
			return func(r rune) bool { return foldEq(r, n.r) }
		}
		c := n.r
		return func(r rune) bool { return r == c }
	case *classNode:
		set, fold := n.set, n.fold
		return func(r rune) bool { return set.contains(r, fold) }
	case *anyNode:
		if n.dotall {
			return func(r rune) bool { return true }
		}
		return func(r rune) bool { return r != '\n' }
	case *groupNode:
		if n.idx < 0 {
			return singleMatcher(n.sub)
		}
	}
	return nil
}

func (m *matcher) match(n node, pos int, k func(int) bool) bool {
	switch n := n.(type) {
	case *litNode:
		if pos < len(m.in) {
			c := m.in[pos]
			if c == n.r || (n.fold && foldEq(c, n.r)) {
				return k(pos + 1)
			}
		}
		return false
	case *classNode:
		if pos < len(m.in) && n.set.contains(m.in[pos], n.fold) {
			return k(pos + 1)
		}
		return false
	case *anyNode:
		if pos < len(m.in) && (n.dotall || m.in[pos] != '\n') {
			return k(pos + 1)
		}
		return false
	case *emptyNode:
		return k(pos)
	case *seqNode:
		return m.matchSeq(n.items, 0, pos, k)
	case *altNode:
		for _, a := range n.alts {
			if m.match(a, pos, k) {
				return true
			}
		}
		return false
	case *groupNode:
		if n.idx < 0 {
			return m.match(n.sub, pos, k)
		}
		i := 2 * n.idx
		if i+1 >= len(m.caps) {
			return m.match(n.sub, pos, k)
		}
		os, oe := m.caps[i], m.caps[i+1]
		if m.match(n.sub, pos, func(e int) bool {
			ps, pe := m.caps[i], m.caps[i+1]
			m.caps[i], m.caps[i+1] = pos, e
			if k(e) {
				return true
			}
			m.caps[i], m.caps[i+1] = ps, pe
			return false
		}) {
			return true
		}
		m.caps[i], m.caps[i+1] = os, oe
		return false
	case *repNode:
		if single := singleMatcher(n.sub); single != nil {
			return m.matchRepSingle(n, single, pos, k)
		}
		return m.matchRep(n, pos, 0, k)
	case *assertNode:
		if m.assert(n.kind, pos) {
			return k(pos)
		}
		return false
	case *lookNode:
		if n.behind {
			found := false
			lo := 0
			if n.maxLen >= 0 {
				lo = pos - n.maxLen
				if lo < 0 {
					lo = 0
				}
			}
			hi := pos - n.minLen
			saved := make([]int, len(m.caps))
			copy(saved, m.caps)
			for s := hi; s >= lo; s-- {
				if m.match(n.sub, s, func(e int) bool { return e == pos }) {
					found = true
					break
				}
			}
			if found == n.neg {
				copy(m.caps, saved)
				return false
			}
			if n.neg {
				copy(m.caps, saved)
			}
			if k(pos) {
				return true
			}
			copy(m.caps, saved)
			return false
		}
		saved := make([]int, len(m.caps))
		copy(saved, m.caps)
		found := m.match(n.sub, pos, func(e int) bool { return true })
		if found == n.neg {
			copy(m.caps, saved)
			return false
		}
		if n.neg {
			copy(m.caps, saved)
		}
		if k(pos) {
			return true
		}
		copy(m.caps, saved)
		return false
	case *atomicNode:
		end := -1
		saved := make([]int, len(m.caps))
		copy(saved, m.caps)
		if !m.match(n.sub, pos, func(e int) bool { end = e; return true }) {
			return false
		}
		if k(end) {
			return true
		}
		copy(m.caps, saved)
		return false
	case *backrefNode:
		i := 2 * n.idx
		if i+1 >= len(m.caps) || m.caps[i] < 0 {
			return false
		}
		s, e := m.caps[i], m.caps[i+1]
		l := e - s
		if pos+l > len(m.in) {
			return false
		}
		for j := 0; j < l; j++ {
			a, b := m.in[s+j], m.in[pos+j]
			if a != b && !(n.fold && foldEq(a, b)) {
				return false
			}
		}
		return k(pos + l)
	}
	panic("unknown node")
}

func (m *matcher) matchSeq(items []node, i int, pos int, k func(int) bool) bool {
	if i == len(items) {
		return k(pos)
	}
	// Fast path for runs of literal/class nodes.
	for i < len(items) {
		switch n := items[i].(type) {
		case *litNode:
			if pos < len(m.in) && (m.in[pos] == n.r || (n.fold && foldEq(m.in[pos], n.r))) {
				pos++
				i++
				continue
			}
			return false
		case *classNode:
			if pos < len(m.in) && n.set.contains(m.in[pos], n.fold) {
				pos++
				i++
				continue
			}
			return false
		case *anyNode:
			if pos < len(m.in) && (n.dotall || m.in[pos] != '\n') {
				pos++
				i++
				continue
			}
			return false
		case *assertNode:
			if m.assert(n.kind, pos) {
				i++
				continue
			}
			return false
		}
		break
	}
	if i == len(items) {
		return k(pos)
	}
	if i == len(items)-1 {
		return m.match(items[i], pos, k)
	}
	return m.match(items[i], pos, func(e int) bool {
		return m.matchSeq(items, i+1, e, k)
	})
}

func (m *matcher) matchRepSingle(n *repNode, single func(rune) bool, pos int, k func(int) bool) bool {
	if n.greedy {
		cnt := 0
		for (n.max < 0 || cnt < n.max) && pos+cnt < len(m.in) && single(m.in[pos+cnt]) {
			cnt++
		}
		for c := cnt; c >= n.min; c-- {
			if k(pos + c) {
				return true
			}
		}
		return false
	}
	c := 0
	for {
		if c >= n.min {
			if k(pos + c) {
				return true
			}
		}
		if n.max >= 0 && c >= n.max {
			return false
		}
		if pos+c >= len(m.in) || !single(m.in[pos+c]) {
			return false
		}
		c++
	}
}

func (m *matcher) matchRep(n *repNode, pos int, count int, k func(int) bool) bool {
	if n.greedy {
		if n.max < 0 || count < n.max {
			if m.match(n.sub, pos, func(e int) bool {
				if e == pos && count >= n.min {
					return false
				}
				return m.matchRep(n, e, count+1, k)
			}) {
				return true
			}
		}
		if count >= n.min {
			return k(pos)
		}
		return false
	}
	if count >= n.min {
		if k(pos) {
			return true
		}
	}
	if n.max < 0 || count < n.max {
		return m.match(n.sub, pos, func(e int) bool {
			if e == pos && count >= n.min {
				return false
			}
			return m.matchRep(n, e, count+1, k)
		})
	}
	return false
}

func (m *matcher) assert(kind int, pos int) bool {
	in := m.in
	switch kind {
	case assertBOL:
		return pos == 0 || in[pos-1] == '\n'
	case assertEOL:
		return pos == len(in) || in[pos] == '\n'
	case assertBOLNoML, assertBOT:
		return pos == 0
	case assertEOLNoML, assertEOTNL:
		return pos == len(in) || (pos == len(in)-1 && in[pos] == '\n')
	case assertEOT:
		return pos == len(in)
	case assertWordB, assertNotWordB:
		a := pos > 0 && isBoundaryWordRune(in[pos-1])
		b := pos < len(in) && isBoundaryWordRune(in[pos])
		if kind == assertWordB {
			return a != b
		}
		return a == b
	case assertStart:
		return pos == m.start
	}
	return false
}
