cat > /workspace/regex/charset.go <<'EOF'
package regex

import "unicode"

type runeRange struct {
	lo, hi rune
}

type charSet struct {
	negate    bool
	ranges    []runeRange
	tables    []*unicode.RangeTable
	negTables []*unicode.RangeTable
	word      bool
	negWord   bool
	space     bool
	negSpace  bool
	subtract  *charSet
	// ascii fast path bitmap for ranges
	ascii    [4]uint64
	asciiSet bool
}

func newCharSet() *charSet { return &charSet{} }

func (s *charSet) addRange(lo, hi rune) {
	s.ranges = append(s.ranges, runeRange{lo, hi})
	s.asciiSet = false
}

func (s *charSet) buildASCII() {
	s.ascii = [4]uint64{}
	for _, r := range s.ranges {
		lo, hi := r.lo, r.hi
		if lo > 255 {
			continue
		}
		if hi > 255 {
			hi = 255
		}
		for c := lo; c <= hi; c++ {
			s.ascii[c>>6] |= 1 << (uint(c) & 63)
		}
	}
	s.asciiSet = true
}

// isWordRune reports whether r is a .NET word character (\w).
func isWordRune(r rune) bool {
	if r < 128 {
		return r == '_' || (r >= '0' && r <= '9') || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z')
	}
	return unicode.IsLetter(r) || unicode.Is(unicode.Mn, r) || unicode.Is(unicode.Nd, r) || unicode.Is(unicode.Pc, r)
}

func isBoundaryWordRune(r rune) bool {
	return isWordRune(r) || r == 0x200c || r == 0x200d
}

// isSpaceRune reports whether r is a .NET whitespace character (\s).
func isSpaceRune(r rune) bool {
	switch r {
	case ' ', '\t', '\n', '\v', '\f', '\r', 0x85:
		return true
	}
	if r < 128 {
		return false
	}
	return unicode.Is(unicode.Z, r)
}

func (s *charSet) matchesRaw(r rune) bool {
	if r < 256 {
		if !s.asciiSet {
			s.buildASCII()
		}
		if s.ascii[r>>6]&(1<<(uint(r)&63)) != 0 {
			return true
		}
	} else {
		for _, rg := range s.ranges {
			if r >= rg.lo && r <= rg.hi {
				return true
			}
		}
	}
	for _, t := range s.tables {
		if unicode.Is(t, r) {
			return true
		}
	}
	for _, t := range s.negTables {
		if !unicode.Is(t, r) {
			return true
		}
	}
	if s.word && isWordRune(r) {
		return true
	}
	if s.negWord && !isWordRune(r) {
		return true
	}
	if s.space && isSpaceRune(r) {
		return true
	}
	if s.negSpace && !isSpaceRune(r) {
		return true
	}
	return false
}

func (s *charSet) contains(r rune, fold bool) bool {
	m := s.matchesRaw(r)
	if !m && fold {
		lr := unicode.ToLower(r)
		if lr != r {
			m = s.matchesRaw(lr)
		}
		if !m {
			ur := unicode.ToUpper(r)
			if ur != r {
				m = s.matchesRaw(ur)
			}
		}
		if !m {
			// handle other simple folds
			for f := unicode.SimpleFold(r); f != r; f = unicode.SimpleFold(f) {
				if s.matchesRaw(f) {
					m = true
					break
				}
			}
		}
	}
	if m && s.subtract != nil && s.subtract.contains(r, fold) {
		m = false
	}
	if s.negate {
		return !m
	}
	return m
}
