package chroma

import "fmt"

// Token output to formatter.
type Token struct {
	Type  TokenType
	Value string
}

func (t Token) String() string   { return t.Value }
func (t Token) GoString() string { return fmt.Sprintf("&Token{%s, %q}", t.Type, t.Value) }

// EOF is returned by lexers at the end of input.
var EOF Token

// Iterator returns tokens until EOF.
type Iterator func() Token

// Tokens consumes all tokens from the iterator.
func (i Iterator) Tokens() []Token {
	var out []Token
	for t := i(); t != EOF; t = i() {
		out = append(out, t)
	}
	return out
}

// Concaterator concatenates tokens from a series of iterators.
func Concaterator(iterators ...Iterator) Iterator {
	return func() Token {
		for len(iterators) > 0 {
			t := iterators[0]()
			if t != EOF {
				return t
			}
			iterators = iterators[1:]
		}
		return EOF
	}
}

// Literator converts a sequence of literal Tokens into an Iterator.
func Literator(tokens ...Token) Iterator {
	return func() Token {
		if len(tokens) == 0 {
			return EOF
		}
		token := tokens[0]
		tokens = tokens[1:]
		return token
	}
}

// SplitTokensIntoLines splits tokens containing newlines in two.
func SplitTokensIntoLines(tokens []Token) (out [][]Token) {
	var line []Token
	for _, token := range tokens {
		for strings_Contains(token.Value, '\n') {
			parts := splitAfterFirstNewline(token.Value)
			// Token becomes the tail.
			line = append(line, Token{Value: parts[0], Type: token.Type})
			out = append(out, line)
			line = nil
			token.Value = parts[1]
		}
		if token.Value != "" {
			line = append(line, token)
		}
	}
	if len(line) > 0 {
		out = append(out, line)
	}
	// Strip empty trailing token line.
	if len(out) > 0 {
		last := out[len(out)-1]
		if len(last) == 1 && last[0].Value == "" {
			out = out[:len(out)-1]
		}
	}
	return
}

func strings_Contains(s string, c byte) bool {
	for i := 0; i < len(s); i++ {
		if s[i] == c {
			return true
		}
	}
	return false
}

func splitAfterFirstNewline(s string) [2]string {
	for i := 0; i < len(s); i++ {
		if s[i] == '\n' {
			return [2]string{s[:i+1], s[i+1:]}
		}
	}
	return [2]string{s, ""}
}
