func (r *RegexLexer) Rules() Rules { return r.rules }

// Config returns the lexer configuration.
func (r *RegexLexer) Config() *Config { return r.config }

// SetRegistry sets the lexer registry (used by Using emitters).
func (r *RegexLexer) SetRegistry(registry *LexerRegistry) Lexer {
	r.registry = registry
	return r
}

// SetAnalyser sets a custom analyser function.
func (r *RegexLexer) SetAnalyser(analyser func(text string) float32) Lexer {
	r.analyser = analyser
	return r
}

// AnalyseText scores the text for this lexer.
func (r *RegexLexer) AnalyseText(text string) float32 {
	if r.analyser != nil {
		return r.analyser(text)
	}
	if r.config.Analyse != nil {
		return r.config.Analyse.score(text)
	}
	return 0
}

func (a *AnalyseConfig) score(text string) float32 {
	var total float32
	for i := range a.Regexes {
		ar := &a.Regexes[i]
		if ar.re == nil {
			re, err := regex.Compile(ar.Pattern, regex.Multiline)
			if err != nil {
				continue
			}
			ar.re = re
		}
		in := []rune(text)
		if ar.re.FindIndex(in, 0) != nil {
			if a.First {
				return ar.Score
			}
			total += ar.Score
		}
	}
	if total > 1 {
		total = 1
	}
	return total
}

func (r *RegexLexer) flags() regex.Flags {
	var f regex.Flags
	if !r.config.NotMultiline {
		f |= regex.Multiline
	}
	if r.config.DotAll {
		f |= regex.DotAll
	}
	if r.config.CaseInsensitive {
		f |= regex.IgnoreCase
	}
	return f
}

func (r *RegexLexer) compile() error {
	if r.compiledOnce {
		return r.compileErr
	}
	r.compiledOnce = true
	// Expand includes.
	expanded := map[string][]Rule{}
	var expand func(state string, seen map[string]bool) []Rule
	expand = func(state string, seen map[string]bool) []Rule {
		if rs, ok := expanded[state]; ok {
			return rs
		}
		if seen[state] {
			return nil
		}
		seen[state] = true
		var out []Rule
		for _, rule := range r.rules[state] {
			if rule.Include != "" {
				out = append(out, expand(rule.Include, seen)...)
				continue
			}
			out = append(out, rule)
		}
		delete(seen, state)
		expanded[state] = out
		return out
	}
	for state := range r.rules {
		expand(state, map[string]bool{})
	}
	// Process combined mutators: create combined states.
	r.compiled = map[string][]*CompiledRule{}
	flags := r.flags()
	var compileState func(state string) error
	compileState = func(state string) error {
		if _, ok := r.compiled[state]; ok {
			return nil
		}
		rules := expanded[state]
		var out []*CompiledRule
		r.compiled[state] = out // placeholder for recursion
		for _, rule := range rules {
			cr := &CompiledRule{Rule: rule}
			if !rule.IsDefault {
				re, err := regex.Compile(rule.Pattern, flags)
				if err != nil {
					r.compileErr = fmt.Errorf("%s: %s: %w", r.config.Name, state, err)
					return r.compileErr
				}
				cr.Regexp = re
			}
			if cm, ok := rule.Mutator.(*combinedMutator); ok {
				name := "__combined_" + strings.Join(cm.states, "__")
				if _, exists := expanded[name]; !exists {
					var combined []Rule
					for _, s := range cm.states {
						combined = append(combined, expanded[s]...)
					}
					expanded[name] = combined
				}
				cr.Mutator = Push(name)
			}
			out = append(out, cr)
		}
		r.compiled[state] = out
		return nil
	}
	states := make([]string, 0, len(expanded))
	for s := range expanded {
		states = append(states, s)
	}
	for _, s := range states {
		if err := compileState(s); err != nil {
			return err
		}
	}
	// Compile any combined states created.
	for {
		added := false
		for s := range expanded {
			if _, ok := r.compiled[s]; !ok {
				if err := compileState(s); err != nil {
					return err
				}
				added = true
			}
		}
		if !added {
			break
		}
	}
	return nil
}

// Tokenise implements Lexer.
func (r *RegexLexer) Tokenise(options *TokeniseOptions, text string) (Iterator, error) {
	if err := r.compile(); err != nil {
		return nil, err
	}
	if options == nil {
		options = &TokeniseOptions{State: "root", EnsureLF: true}
	}
	if options.EnsureLF {
		text = ensureLF(text)
	}
	newlineAdded := false
	if !options.Nested && r.config.EnsureNL && !strings.HasSuffix(text, "\n") {
		text += "\n"
		newlineAdded = true
	}
	state := &LexerState{
		Lexer:          r,
		Registry:       r.registry,
		Text:           []rune(text),
		Stack:          []string{options.State},
		Rules:          r.compiled,
		MutatorContext: map[interface{}]interface{}{},
		options:        options,
		newlineAdded:   newlineAdded,
	}
	return state.Iterator, nil
}

func ensureLF(text string) string {
	if !strings.Contains(text, "\r") {
		return text
	}
	var sb strings.Builder
	sb.Grow(len(text))
	for i := 0; i < len(text); i++ {
		c := text[i]
		if c == '\r' {
			if i+1 < len(text) && text[i+1] == '\n' {
				continue
			}
			sb.WriteByte('\n')
			continue
		}
		sb.WriteByte(c)
	}
	return sb.String()
}

// Tokenise text using the given lexer with default options.
func Tokenise(lexer Lexer, options *TokeniseOptions, text string) ([]Token, error) {
	it, err := lexer.Tokenise(options, text)
	if err != nil {
		return nil, err
	}
	return it.Tokens(), nil
}
