			if b.emitters[i] != nil {
				iterators = append(iterators, b.emitters[i].Emit([]string{group}, state))
			}
		}
	}
	return Concaterator(iterators...)
}

// UsingByGroup emits tokens for the matched groups in the regex using a
// sublexer selected by the group at sublexerNameGroup, with the code at
// codeGroup. Other groups are emitted with the given emitters.
func UsingByGroup(sublexerNameGroup, codeGroup int, emitters ...Emitter) Emitter {
	return &usingByGroup{sublexerNameGroup: sublexerNameGroup, codeGroup: codeGroup, emitters: emitters}
}

type usingByGroup struct {
	sublexerNameGroup int
	codeGroup         int
	emitters          []Emitter
}

func (u *usingByGroup) Emit(groups []string, state *LexerState) Iterator {
	if len(u.emitters) != len(groups)-1 {
		panic(fmt.Errorf("number of groups %q does not match number of emitters %v", groups, u.emitters))
	}
	iterators := make([]Iterator, 0, len(groups)-1)
	var lexer Lexer
	if state.Registry != nil {
		lexer = state.Registry.Get(groups[u.sublexerNameGroup])
	}
	for i, group := range groups[1:] {
		if i == u.codeGroup-1 && lexer != nil {
			it, err := lexer.Tokenise(&TokeniseOptions{State: "root", Nested: true}, groups[u.codeGroup])
			if err != nil {
				panic(err)
			}
			iterators = append(iterators, it)
		} else if u.emitters[i] != nil {
			iterators = append(iterators, u.emitters[i].Emit([]string{group}, state))
		}
	}
	return Concaterator(iterators...)
}

