package chroma

import (
	"fmt"
	"math"
	"strings"
)

// Colour represents an RGB colour. Zero value means unset.
type Colour int32

// NewColour creates a Colour from RGB components.
func NewColour(r, g, b uint8) Colour {
	return Colour(int32(r)<<16|int32(g)<<8|int32(b)) + 1
}

// ParseColour parses a #rgb or #rrggbb colour string, or returns 0.
func ParseColour(colour string) Colour {
	colour = normaliseColour(colour)
	n, err := parseHexColour(colour)
	if err != nil {
		return 0
	}
	return Colour(n) + 1
}

func parseHexColour(s string) (int64, error) {
	if len(s) != 6 {
		return 0, fmt.Errorf("invalid colour %q", s)
	}
	var n int64
	for _, c := range s {
		var v int64
		switch {
		case c >= '0' && c <= '9':
			v = int64(c - '0')
		case c >= 'a' && c <= 'f':
			v = int64(c-'a') + 10
		case c >= 'A' && c <= 'F':
			v = int64(c-'A') + 10
		default:
			return 0, fmt.Errorf("invalid colour %q", s)
		}
		n = n*16 + v
	}
	return n, nil
}

// MustParseColour is like ParseColour but panics if the colour is invalid.
func MustParseColour(colour string) Colour {
	parsed := ParseColour(colour)
	if !parsed.IsSet() {
		panic(fmt.Errorf("invalid colour %q", colour))
	}
	return parsed
}

// IsSet returns true if the colour is set.
func (c Colour) IsSet() bool { return c != 0 }

func (c Colour) String() string   { return fmt.Sprintf("#%06x", int(c-1)) }
func (c Colour) GoString() string { return fmt.Sprintf("Colour(0x%06x)", int(c-1)) }

// Red component.
func (c Colour) Red() uint8 { return uint8(((c - 1) >> 16) & 0xff) }

// Green component.
func (c Colour) Green() uint8 { return uint8(((c - 1) >> 8) & 0xff) }

// Blue component.
func (c Colour) Blue() uint8 { return uint8((c - 1) & 0xff) }

// Brightness of the colour (roughly) in the range 0.0 to 1.0.
func (c Colour) Brightness() float64 {
	return (float64(c.Red()) + float64(c.Green()) + float64(c.Blue())) / 255.0 / 3.0
}

// Brighten the colour by the given factor.
func (c Colour) Brighten(factor float64) Colour {
	r := float64(c.Red())
	g := float64(c.Green())
	b := float64(c.Blue())
	if factor < 0 {
		factor++
		r *= factor
		g *= factor
		b *= factor
	} else {
		r = (255-r)*factor + r
		g = (255-g)*factor + g
		b = (255-b)*factor + b
	}
	return NewColour(uint8(r), uint8(g), uint8(b))
}

// BrightenOrDarken brightens a colour if it is < 0.5 brightness or darkens if > 0.5 brightness.
func (c Colour) BrightenOrDarken(factor float64) Colour {
	if c.Brightness() < 0.5 {
		return c.Brighten(factor)
	}
	return c.Brighten(-factor)
}

// ClampBrightness returns a copy of this colour with its brightness adjusted such that
// it falls within the range [min, max] (or very close to it due to rounding errors).
func (c Colour) ClampBrightness(min, max float64) Colour {
	if !c.IsSet() {
		return c
	}
	min = math.Max(min, 0)
	max = math.Min(max, 1)
	current := c.Brightness()
	target := math.Min(math.Max(current, min), max)
	if current == target {
		return c
	}
	r := float64(c.Red())
	g := float64(c.Green())
	b := float64(c.Blue())
	rgb := []*float64{&r, &g, &b}
	if target > current {
		// Brighten.
		for _, p := range rgb {
			*p = (255-*p)*((target-current)/(1-current)) + *p
		}
	} else {
		for _, p := range rgb {
			*p *= target / current
		}
	}
	return NewColour(uint8(r), uint8(g), uint8(b))
}

// Distance between this colour and another (approximate perceptual distance).
func (c Colour) Distance(e2 Colour) float64 {
	ar, ag, ab := float64(c.Red()), float64(c.Green()), float64(c.Blue())
	br, bg, bb := float64(e2.Red()), float64(e2.Green()), float64(e2.Blue())
	rmean := (ar + br) / 2
	r := ar - br
	g := ag - bg
	b := ab - bb
	return math.Sqrt((((512 + rmean) * r * r) / 256) + 4*g*g + (((767 - rmean) * b * b) / 256))
}

func normaliseColour(colour string) string {
	if strings.HasPrefix(colour, "#") {
		colour = colour[1:]
		if len(colour) == 3 {
			for _, c := range colour {
				colour += string(c) + string(c)
			}
			colour = colour[3:]
		}
	}
	return colour
}
