	}
	fgToBg8 := func(s string) string {
		return strings.ReplaceAll(s, "[3", "[4")
	}
	fgToBg16 := func(s string) string {
		s = strings.ReplaceAll(s, "\033[3", "\033[4")
		s = strings.ReplaceAll(s, "\033[9", "\033[10")
