func writeToken(w io.Writer, clr string, value string) {
	if clr == "" {
		fmt.Fprint(w, value)
		return
	}
	for value != "" {
		idx := strings.IndexByte(value, '\n')
		var line string
		if idx < 0 {
			line = value
			value = ""
		} else {
			line = value[:idx+1]
			value = value[idx+1:]
		}
		if strings.HasSuffix(line, "\n") {
			fmt.Fprint(w, clr+line[:len(line)-1]+"\033[0m\n")
		} else {
