// XML representation of a lexer.
type xmlLexer struct {
	XMLName xml.Name  `xml:"lexer"`
	Config  xmlConfig `xml:"config"`
	Rules   xmlRules  `xml:"rules"`
}

type xmlConfig struct {
	Name            string          `xml:"name"`
	Aliases         []string        `xml:"alias"`
