	NotMultiline    bool            `xml:"not_multiline"`
	EnsureNL        bool            `xml:"ensure_nl"`
	Priority        float32         `xml:"priority"`
	Analyse         *xmlAnalyse     `xml:"analyse"`
}

type xmlAnalyse struct {
	First   bool              `xml:"first,attr"`
	Regexes []xmlAnalyseRegex `xml:"regex"`
}

type xmlAnalyseRegex struct {
	Pattern string  `xml:"pattern,attr"`
	Score   float32 `xml:"score,attr"`
}

type xmlRules struct {
	States []xmlState `xml:"state"`
}

type xmlState struct {
	Name  string    `xml:"name,attr"`
	Rules []xmlRule `xml:"rule"`
}

type xmlRule struct {
	Pattern  string `xml:"pattern,attr"`
	Inner    []byte `xml:",innerxml"`
}

type xmlElem struct {
	XMLName xml.Name
	Attrs   []xml.Attr `xml:",any,attr"`
	Inner   []byte     `xml:",innerxml"`
}

func (e *xmlElem) attr(name string) string {
	for _, a := range e.Attrs {
		if a.Name.Local == name {
			return a.Value
		}
	}
	return ""
}

func (e *xmlElem) attrs(name string) []string {
	var out []string
	for _, a := range e.Attrs {
		if a.Name.Local == name {
			out = append(out, a.Value)
		}
	}
	return out
}

func parseElems(inner []byte) ([]xmlElem, error) {
	dec := xml.NewDecoder(strings.NewReader("<r>" + string(inner) + "</r>"))
	var wrapper struct {
		Elems []xmlElem `xml:",any"`
	}
	if err := dec.Decode(&wrapper); err != nil {
		return nil, err
	}
	return wrapper.Elems, nil
}

// NewXMLLexer creates a new RegexLexer from XML.
func NewXMLLexer(r io.Reader) (*RegexLexer, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	return ParseXMLLexer(data)
}

// ParseXMLLexer parses a lexer definition from XML bytes.
func ParseXMLLexer(data []byte) (*RegexLexer, error) {
	var lx xmlLexer
	if err := xml.Unmarshal(data, &lx); err != nil {
		return nil, err
	}
	config := &Config{
		Name:            lx.Config.Name,
		Aliases:         lx.Config.Aliases,
		Filenames:       lx.Config.Filenames,
		AliasFilenames:  lx.Config.AliasFilenames,
		MimeTypes:       lx.Config.MimeTypes,
		CaseInsensitive: lx.Config.CaseInsensitive,
		DotAll:          lx.Config.DotAll,
		NotMultiline:    lx.Config.NotMultiline,
		EnsureNL:        lx.Config.EnsureNL,
		Priority:        lx.Config.Priority,
	}
	if lx.Config.Analyse != nil {
		ac := &AnalyseConfig{First: lx.Config.Analyse.First}
		for _, r := range lx.Config.Analyse.Regexes {
			ac.Regexes = append(ac.Regexes, AnalyseRegex{Pattern: r.Pattern, Score: r.Score})
		}
		config.Analyse = ac
	}
	rules := Rules{}
	for _, state := range lx.Rules.States {
		var out []Rule
		for _, xr := range state.Rules {
			rule, err := parseXMLRule(xr)
			if err != nil {
				return nil, fmt.Errorf("%s: state %q: %w", config.Name, state.Name, err)
			}
			out = append(out, rule)
		}
		rules[state.Name] = out
	}
	return NewLexer(config, rules), nil
}

func parseXMLRule(xr xmlRule) (Rule, error) {
	elems, err := parseElems(xr.Inner)
	if err != nil {
		return Rule{}, err
	}
	rule := Rule{Pattern: xr.Pattern}
	var mutators []Mutator
	hasPattern := false
	// Determine if a pattern attribute was present: encoding/xml gives "" for both
	// missing and empty; we treat rules with no pattern and no emitter as default.
	for _, e := range elems {
		switch e.XMLName.Local {
		case "include":
			rule.Include = e.attr("state")
			return rule, nil
		case "token", "bygroups", "using", "usingself", "usingbygroup":
			em, err := parseEmitter(e)
			if err != nil {
				return Rule{}, err
			}
			rule.Type = em
		case "push", "pop", "combined", "mutators":
			ms, err := parseMutator(e)
			if err != nil {
				return Rule{}, err
			}
			mutators = append(mutators, ms...)
		default:
			return Rule{}, fmt.Errorf("unknown rule element %q", e.XMLName.Local)
		}
	}
	_ = hasPattern
	if len(mutators) == 1 {
		rule.Mutator = mutators[0]
	} else if len(mutators) > 1 {
		rule.Mutator = Mutators(mutators...)
	}
	if xr.Pattern == "" && !xmlHasPatternAttr(xr) {
		rule.IsDefault = true
	}
	return rule, nil
}

// xmlHasPatternAttr is a heuristic: encoding/xml cannot distinguish a missing
// attribute from an empty one, so we record presence via a custom unmarshal.
func xmlHasPatternAttr(xr xmlRule) bool {
	return xr.hasPattern
}

func parseEmitter(e xmlElem) (Emitter, error) {
	switch e.XMLName.Local {
	case "token":
		tt, err := TokenTypeString(e.attr("type"))
		if err != nil {
			return nil, err
		}
		return tt, nil
	case "bygroups":
		sub, err := parseElems(e.Inner)
		if err != nil {
			return nil, err
		}
		var emitters []Emitter
		for _, s := range sub {
			em, err := parseEmitter(s)
			if err != nil {
				return nil, err
			}
			emitters = append(emitters, em)
		}
		return ByGroups(emitters...), nil
	case "using":
		return Using(e.attr("lexer")), nil
	case "usingself":
		return UsingSelf(e.attr("state")), nil
	case "usingbygroup":
		sg, _ := strconv.Atoi(e.attr("sublexer_name_group"))
		cg, _ := strconv.Atoi(e.attr("code_group"))
		sub, err := parseElems(e.Inner)
		if err != nil {
			return nil, err
		}
		var emitters []Emitter
		for _, s := range sub {
			em, err := parseEmitter(s)
			if err != nil {
				return nil, err
			}
			emitters = append(emitters, em)
		}
		return UsingByGroup(sg, cg, emitters...), nil
	}
	return nil, fmt.Errorf("unknown emitter %q", e.XMLName.Local)
}

func parseMutator(e xmlElem) ([]Mutator, error) {
	switch e.XMLName.Local {
	case "push":
		return []Mutator{Push(e.attrs("state")...)}, nil
	case "pop":
		depth := 1
		if d := e.attr("depth"); d != "" {
			depth, _ = strconv.Atoi(d)
		}
		return []Mutator{Pop(depth)}, nil
	case "combined":
		return []Mutator{Combined(e.attrs("state")...)}, nil
	case "mutators":
		sub, err := parseElems(e.Inner)
		if err != nil {
			return nil, err
		}
		var out []Mutator
		for _, s := range sub {
			ms, err := parseMutator(s)
			if err != nil {
				return nil, err
			}
			out = append(out, ms...)
		}
		return out, nil
	}
	return nil, fmt.Errorf("unknown mutator %q", e.XMLName.Local)
}

// UnmarshalXML records whether the pattern attribute was present.
func (r *xmlRule) UnmarshalXML(d *xml.Decoder, start xml.StartElement) error {
	for _, a := range start.Attr {
		if a.Name.Local == "pattern" {
			r.Pattern = a.Value
			r.hasPattern = true
		}
	}
	var inner struct {
		Inner []byte `xml:",innerxml"`
	}
	if err := d.DecodeElement(&inner, &start); err != nil {
		return err
	}
	r.Inner = inner.Inner
	return nil
}
