def brighten(c, f):
    r,g,b = int(c[1:3],16), int(c[3:5],16), int(c[5:7],16)
    if f < 0:
        f += 1; r*=f; g*=f; b*=f
    else:
        r = (255-r)*f + r; g = (255-g)*f + g; b = (255-b)*f + b
    return '#%02x%02x%02x' % (int(r), int(g), int(b))
def brightness(c):
    if c is None: return 1.0
    r,g,b = int(c[1:3],16), int(c[3:5],16), int(c[5:7],16)
    return (r+g+b)/255.0/3.0
def bod(c, f):
    if c is None:
        c = '#ffffff'  # unset colour -> components 255
    return brighten(c, f) if brightness(c) < 0.5 else brighten(c, -f)

EMPTY = {'bold':False,'italic':False,'underline':False,'color':None,'bg':None}

def inherit(entry, *ancestors):
    out = dict(entry)
    for anc in reversed(ancestors):
        for k in ('color','bg'):
            if out[k] is None: out[k] = anc[k]
        for k in ('bold','italic','underline'):
            if not out[k]: out[k] = anc[k]
    return out

