    parts = []
    if e['bold']: parts.append('bold')
    if e['italic']: parts.append('italic')
    if e['underline']: parts.append('underline')
    if e['color']: parts.append(e['color'])
    if e['bg']: parts.append('bg:' + e['bg'])
