    for k in ('bold','italic','underline'):
        if target[k] and not base[k]: e[k] = True
    ok = inherit(e, base) == target
    return e, ok

def gen(style):
    got = probe(style)        # Get(T) with Background.bg cleared
    css = parse_css(style)
    bgcss = css_props(css.get('Background',''))
    bg_colour, bg_bg = bgcss['color'], bgcss['bg']
    # terminal probe: tokens lose inherited Background.bg; but an explicit bg equal to bg_bg shows up.
    entries = {}  # type -> entry dict
    # LineNumbers colour tells whether Background has a colour.
    ln = css_props(css.get('LineNumbers','').split('padding: 0 0.4em 0 0.4em;')[-1])
    background_has_colour = bg_colour is not None and ln['color'] == bod(bg_colour, 0.5) and ln['color'] != '#7f7f7f'
    bg_entry = dict(EMPTY); bg_entry['bg'] = bg_bg
    if background_has_colour: bg_entry['color'] = bg_colour
    entries['Background'] = bg_entry
    # Text entry
    text_get = got.get('Text', dict(EMPTY))
    text_full = dict(text_get); 
    if text_full['bg'] is None: text_full['bg'] = bg_bg
    # Get(Text) = inherit(text, bg) = text overridden... text entry wins over bg
    te, ok = diff(text_full, bg_entry)
    # but if Background has colour and text has same -> no need
    entries['Text'] = te
    def get_full(t):
        g = dict(got.get(t, EMPTY))
        if g['bg'] is None: g['bg'] = bg_bg
        return g
    def computed(t):
        # Get(t) using current entries
        own = entries.get(t, EMPTY)
        return inherit(own, entries['Background'], entries['Text'], entries.get(BYVAL.get(cat(t),''), EMPTY) if cat(t) else EMPTY, entries.get(BYVAL.get(subcat(t),''), EMPTY) if subcat(t) else EMPTY)
    order = sorted([t for t in TYPES if t not in ('Background','Text','PreWrapper','Line','LineTable','LineTableTD','LineLink','CodeLine')], key=lambda t: (VALUES[t] % 1000 != 0, VALUES[t] % 100 != 0, VALUES[t]))
    problems = []
    for t in order:
        target = get_full(t)
        if t in ('LineNumbers','LineNumbersTable','LineHighlight'):
            # use CSS
            if t == 'LineHighlight':
                p = css_props(css.get(t, ''))
                synth = {'bold':False,'italic':False,'underline':False,'color':None,'bg': bod(bg_bg, 0.1)}
                target = inherit(dict(EMPTY), entries['Background'], entries['Text'], synth)
                target2 = dict(p); 
                if target2['color'] is None: target2['color'] = bgcss['color']
                if target2['bg'] is None: target2['bg'] = bg_bg
                if target2 == target: continue
                e = {'bold':p['bold'],'italic':p['italic'],'underline':p['underline'],'color':p['color'],'bg':p['bg']}
                entries[t] = e; continue
            else:
                p = css_props(css.get(t,'').split('padding: 0 0.4em 0 0.4em;')[-1])
                synth_col = bod(bg_entry['color'], 0.5)
                if p['color'] == synth_col and not p['bold'] and not p['italic'] and not p['underline'] and p['bg'] is None:
                    continue
                e = {'bold':p['bold'],'italic':p['italic'],'underline':p['underline'],'color':p['color'],'bg':p['bg']}
                entries[t] = e; continue
        base = computed(t)
        if base == target: continue
        # need entry: diff against inherit(base_without_own)
        e, ok = diff(target, base)
        if not ok:
            problems.append((t, target, base))
        entries[t] = e
    # emit XML
    lines = ['<style name="%s">' % style]
    for t in TYPES:
        if t in entries and entry_str(entries[t]):
            lines.append('  <entry type="%s" style="%s"/>' % (t, entry_str(entries[t])))
    lines.append('</style>')
    return '\n'.join(lines) + '\n', problems

if __name__ == '__main__':
    names = subprocess.run([EXE, '--list'], capture_output=True).stdout.decode()
    styles = [l for l in names.splitlines() if l.startswith('styles:')][0].split(':')[1].split()
    os.makedirs(OUT, exist_ok=True)
    for s in styles:
        if s == 'swapoff': continue
        xml, problems = gen(s)
        open(os.path.join(OUT, s + '.xml'), 'w').write(xml)
        if problems: print(s, 'PROBLEMS', problems[:3])
    print('done', len(styles))
