	os.Exit(1)
}

func main() {
	progName = filepath.Base(os.Args[0])
	parseArgs(os.Args[1:])

	if progName == ".lessfilter" {
		cli.Fail = true
	}

	var out io.Writer = os.Stdout
	if !cli.Unbuffered {
		bw := bufio.NewWriterSize(os.Stdout, 16384)
		defer bw.Flush()
		out = bw
	}

	if cli.List {
		listAll(out)
		return
	}

	if cli.JSON {
		cli.Formatter = "json"
	}
	if cli.HTML {
		cli.Formatter = "html"
	}
	if cli.SVG {
		cli.Formatter = "svg"
	}

	// Retrieve user-specified style, clone it, and add some overrides.
	builder := getStyle(cli.Style).Builder()
	if cli.HTMLHighlightStyle != "" {
		builder.Add(chroma.LineHighlight, cli.HTMLHighlightStyle)
	}
	if cli.HTMLLinesStyle != "" {
		builder.Add(chroma.LineNumbers, cli.HTMLLinesStyle)
	}
	style, err := builder.Build()
	if err != nil {
		fatalf("%s", err)
	}

	// Dump styles.
	if cli.HTMLStyles {
		formatter := html.New(html.WithClasses(true))
		if err := formatter.WriteCSS(out, style); err != nil {
			fatalf("%s", err)
		}
		return
	}

	if cli.Formatter == "html" {
		options := []html.Option{
			html.TabWidth(cli.HTMLTabWidth),
			html.BaseLineNumber(cli.HTMLBaseLine),
		}
		if cli.HTMLPrefix != "" {
			options = append(options, html.ClassPrefix(cli.HTMLPrefix))
		}

		// Dump styles.
		if !cli.HTMLInlineStyles {
			options = append(options, html.WithClasses(true))
		}
		if !cli.HTMLOnly {
			options = append(options, html.Standalone(true))
		}
		if cli.HTMLLines {
			options = append(options, html.WithLineNumbers(true))
		}
		if cli.HTMLLinesTable {
			options = append(options, html.LineNumbersInTable(true))
		}
		if cli.HTMLPreventSurroundingPre {
			options = append(options, html.PreventSurroundingPre(true))
		}
		if cli.HTMLLinkableLines {
			options = append(options, html.WithLinkableLineNumbers(true, "L"))
		}
		if cli.HTMLAllStyles {
			options = append(options, html.WithAllClasses(true))
		}
		if len(cli.HTMLHighlight) > 0 {
			ranges := [][2]int{}
			for _, span := range strings.Split(cli.HTMLHighlight, ",") {
				parts := strings.Split(span, ":")
				if len(parts) > 2 {
					fatalf("range should be N[:M], not %q", span)
				}
				start, err := strconv.ParseInt(parts[0], 10, 64)
				if err != nil {
					fatalf("min value of range should be integer not %q: %s", parts[0], err)
				}
				end := start
				if len(parts) == 2 {
					end, err = strconv.ParseInt(parts[1], 10, 64)
					if err != nil {
						fatalf("max value of range should be integer not %q: %s", parts[1], err)
					}
				}
				ranges = append(ranges, [2]int{int(start), int(end)})
			}
			options = append(options, html.HighlightLines(ranges))
		}
		formatters.Register("html", html.New(options...))
	}
