func listAll(w io.Writer) {
	fmt.Fprintln(w, "lexers:")
	sort.Sort(lexers.GlobalLexerRegistry.Lexers)
	for _, l := range lexers.GlobalLexerRegistry.Lexers {
		config := l.Config()
		fmt.Fprintln(w, "  "+config.Name)
		if len(config.Aliases) > 0 {
			fmt.Fprintln(w, "    aliases: "+strings.Join(config.Aliases, " "))
		}
		if len(config.Filenames) > 0 {
			fmt.Fprintln(w, "    filenames: "+strings.Join(config.Filenames, " "))
		}
		if len(config.MimeTypes) > 0 {
			fmt.Fprintln(w, "    mimetypes: "+strings.Join(config.MimeTypes, " "))
		}
	}
	fmt.Fprintln(w, "styles: "+strings.Join(styles.Names(), " "))
	fmt.Fprintln(w, "formatters: "+strings.Join(formatters.Names(), " "))
}

func selexer(path, contents string) chroma.Lexer {
	var lexer chroma.Lexer
	if cli.Lexer != "autodetect" {
		lexer = lexers.Get(cli.Lexer)
		if lexer == nil {
			if _, err := os.Stat(cli.Lexer); err == nil {
				lexer = loadLexerFile(cli.Lexer)
			}
		}
	} else {
		if path != "" {
			lexer = lexers.Match(path)
		}
		if lexer == nil {
			lexer = lexers.Analyse(contents)
		}
	}
	if lexer == nil {
		if cli.Fail {
			os.Exit(1)
		}
		lexer = lexers.Fallback
	}
	if rl, ok := lexer.(*chroma.RegexLexer); ok {
		rl.Trace(cli.Trace)
	}
	return lexer
}

func loadLexerFile(path string) chroma.Lexer {
	cwd, err := os.Getwd()
	if err != nil {
		fatalf("%s", err)
	}
	rel, err := filepath.Rel(cwd, path)
	if err != nil {
		fatalf("%s", err)
	}
	// Emulate fs.FS path validation.
	if !validFSPath(rel) {
		fatalf("open %s: invalid argument", rel)
	}
	data, err := os.ReadFile(filepath.Join(cwd, rel))
	if err != nil {
		fatalf("%s", err)
	}
	lexer, err := chroma.ParseXMLLexer(data)
	if err != nil {
		fatalf("%s", err)
	}
	return lexer
}

func validFSPath(name string) bool {
	if !utf8.ValidString(name) {
		return false
	}
	if name == "." {
		return true
	}
	for {
		i := 0
		for i < len(name) && name[i] != '/' {
			i++
		}
		elem := name[:i]
		if elem == "" || elem == "." || elem == ".." {
			return false
		}
		if i == len(name) {
			return true
		}
		name = name[i+1:]
	}
}

func format(w io.Writer, style *chroma.Style, lexer chroma.Lexer, contents string) {
	formatter := getFormatter()
	lexer = chroma.Coalesce(lexer)
	it, err := lexer.Tokenise(nil, contents)
	if err != nil {
		fatalf("%s", err)
	}
	if err := formatter.Format(w, style, it); err != nil {
		fatalf("%s", err)
	}
}

func getFormatter() chroma.Formatter {
	return formatters.Get(cli.Formatter)
}

func check(filename string, lexer chroma.Lexer, contents string) {
	lexer = chroma.Coalesce(lexer)
	it, err := lexer.Tokenise(nil, contents)
	if err != nil {
		fatalf("%s", err)
	}
	line, col := 1, 0
	for token := it(); token != chroma.EOF; token = it() {
		if token.Type == chroma.Error {
			fmt.Printf("%s:%d:%d %q\n", filename, line, col, token.Value)
		}
		for _, c := range token.String() {
			col++
			if c == '\n' {
				line, col = line+1, 0
			}
		}
	}
}
