type flagKind int

const (
	kindBool flagKind = iota
	kindString
	kindInt
)

type flagDef struct {
	long  string
	short string
	kind  flagKind
	set   func(string) error
	hook  func() // for help/version
}

var flagDefs []*flagDef

func parseError(format string, args ...interface{}) {
	fmt.Fprintf(os.Stderr, "%s: error: %s\n", progName, fmt.Sprintf(format, args...))
	os.Exit(80)
}

func boolFlag(long, short string, dst *bool) *flagDef {
	return &flagDef{long: long, short: short, kind: kindBool, set: func(v string) error {
		switch strings.ToLower(v) {
		case "true", "1", "yes":
			*dst = true
		case "false", "0", "no":
			*dst = false
		default:
			return fmt.Errorf("bool value must be true, 1, yes, false, 0 or no but got %q", v)
		}
		return nil
	}}
}

func stringFlag(long, short string, dst *string) *flagDef {
	return &flagDef{long: long, short: short, kind: kindString, set: func(v string) error {
		*dst = v
		return nil
	}}
}

func intFlag(long, short string, dst *int) *flagDef {
	return &flagDef{long: long, short: short, kind: kindInt, set: func(v string) error {
		n, err := strconv.ParseInt(v, 0, 64)
		if err != nil {
			return fmt.Errorf("expected a valid 64 bit int but got %q", v)
		}
		*dst = int(n)
		return nil
	}}
}

func initFlags() {
	var help, version bool
	flagDefs = []*flagDef{
