			fmt.Printf(helpTemplate, progName)
			os.Exit(0)
		}
	}
	flagDefs[1].hook = func() {
		if version {
			fmt.Printf("%s-%s-%s\n", version_(), commit, date)
			os.Exit(0)
		}
	}
}

func version_() string { return version }

func findLong(name string) *flagDef {
	for _, f := range flagDefs {
		if f.long == name {
			return f
		}
	}
	return nil
}

func findShort(name string) *flagDef {
	for _, f := range flagDefs {
		if f.short != "" && f.short == name {
			return f
		}
	}
	return nil
}

func levenshtein(a, b string) int {
	ar, br := []rune(a), []rune(b)
	prev := make([]int, len(br)+1)
	cur := make([]int, len(br)+1)
	for j := range prev {
		prev[j] = j
	}
	for i := 1; i <= len(ar); i++ {
		cur[0] = i
		for j := 1; j <= len(br); j++ {
			cost := 1
			if ar[i-1] == br[j-1] {
				cost = 0
			}
			cur[j] = min3(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
		}
		prev, cur = cur, prev
	}
	return prev[len(br)]
